public class Obskorb {

    public static void main(String[] args) {
        String[] obst = {"Apfel", "Banane", "Kirsche"};

        System.out.println("Erster Eintrag: " + obst[0]);
        System.out.println("Letzter Eintrag: " + obst[obst.length - 1]);
        System.out.println("Anzahl: " + obst.length);

        obst[1] = "Birne";
        System.out.println("Jetzt in der Mitte: " + obst[1]);
    }
}

